"use strict";(self.webpackChunksite=self.webpackChunksite||[]).push([[567],{5226:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/","label":"PlanetsLib","docId":"intro","unlisted":false},{"type":"category","label":"Usage documentation","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/usage-documentation/entity-replacement-system","label":"Entity Replacement System","docId":"usage-documentation/entity-replacement-system","unlisted":false},{"type":"link","href":"/usage-documentation/orbit-graphics","label":"Orbit Graphics","docId":"usage-documentation/orbit-graphics","unlisted":false},{"type":"link","href":"/usage-documentation/planet-properties","label":"Special Planet Properties","docId":"usage-documentation/planet-properties","unlisted":false},{"type":"link","href":"/usage-documentation/recipe-events","label":"Recipe Events","docId":"usage-documentation/recipe-events","unlisted":false},{"type":"link","href":"/usage-documentation/rocket-part-recipes","label":"Rocket Part Recipes","docId":"usage-documentation/rocket-part-recipes","unlisted":false},{"type":"link","href":"/usage-documentation/technologies","label":"Science & Technologies","docId":"usage-documentation/technologies","unlisted":false}],"href":"/category/usage-documentation"},{"type":"link","href":"/player-facing-features","label":"Player Facing Features","docId":"player-facing-features","unlisted":false}]},"docs":{"intro":{"id":"intro","title":"PlanetsLib","description":"Code and graphics to help modders creating planets, moons and other systems. This library is a community project. Anyone is welcome to open a pull request on Github. For feature requests, please open an issue. For general discussion, use Discord.","sidebar":"docsSidebar"},"player-facing-features":{"id":"player-facing-features","title":"Player Facing Features","description":"The primary intent of PlanetsLib is to be a library which provides opt-in functionality for other mods. However, a small number of game-affecting or player-interface-affecting features have been added over time. These are listed below, player feedback on them is most welcome in Discord.","sidebar":"docsSidebar"},"usage-documentation/entity-replacement-system":{"id":"usage-documentation/entity-replacement-system","title":"Entity Replacement System","description":"PlanetsLib allows you to quickly generate planet-exclusive variants of entities. On placing an entity on a planet with a planet-exclusive variant, PlanetsLib will replace the original entity with your variant. The difference between entity variants and the original entity are invisible to the user, and variants can not be seen in the Factoriopedia. Every variant must be associated with a boolean startup setting that can be disabled to ease in uninstallation. Once an entity variant has been created, any attempt to create a variant for the same entity for the same planet will throw an error. This is a limitation of the current system that may change in the future. Currently, entity variants that are the same type as their origin entity are well-tested, but changing entity types is untested.","sidebar":"docsSidebar"},"usage-documentation/orbit-graphics":{"id":"usage-documentation/orbit-graphics","title":"Orbit Graphics","description":"Moon orbit graphics","sidebar":"docsSidebar"},"usage-documentation/planet-properties":{"id":"usage-documentation/planet-properties","title":"Special Planet Properties","description":"PlanetsLib allows the addition of \\"special properties\\", values which can be displayed as surface properties, but are not intended to be used as surface properties. These properties are used during data-final-fixes and in control scripts to execute certain behavior.","sidebar":"docsSidebar"},"usage-documentation/recipe-events":{"id":"usage-documentation/recipe-events","title":"Recipe Events","description":"PlanetsLib includes one event that recipes can hook into using RecipePrototype::PlanetsLibrecipeeffects. This event adds items to the machine\'s ingredient inventory on craft. Additional events may be added in the future.","sidebar":"docsSidebar"},"usage-documentation/rocket-part-recipes":{"id":"usage-documentation/rocket-part-recipes","title":"Rocket Part Recipes","description":"You can use the library to assign unique rocket part recipes to rocket silos placed on a specified planet to increase or decrease the difficulty of launching rockets on the planet. Rocket silos with their recipe fixed to the vanilla rocket-part recipe are targeted by PlanetsLib. To implement:","sidebar":"docsSidebar"},"usage-documentation/technologies":{"id":"usage-documentation/technologies","title":"Science & Technologies","description":"* PlanetsLib.getchildtechnologies(techname) \u2014 Returns a list of the names of all technologies that have techname as a prerequisite.","sidebar":"docsSidebar"}}}}')}}]);